using System.Reflection;
using System.Collections;
using CombatSolver.Engine.Common;
using HarmonyLib;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.Entities.Creatures;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Hooks;
using MegaCrit.Sts2.Core.Models;
using STS2RitsuLib.CardPiles;

namespace CombatSolver;

// Experimental root-frozen permission. No model/pile lookup result is cached.
internal static class NativeKeywordFlagsReadCertificate
{
    internal static bool ShouldRetain(CardModel card, CombatRootSnapshot root)
        => root.CanReadLocalKeywordFlags && ReferenceEquals(card._owner, root.PlayerIdentity)
            && card._keywords?.GetType() == typeof(HashSet<CardKeyword>)
                ? card.LocalKeywords.Contains(CardKeyword.Retain) || card._hasSingleTurnRetain
                : card.ShouldRetainThisTurn;

    private const BindingFlags Flags = BindingFlags.Instance | BindingFlags.Static
        | BindingFlags.Public | BindingFlags.NonPublic;
    private static readonly Guid GameModule = new("8a76776c-0ce1-4d4f-90bd-8cce653dad8e");
    private static readonly Guid RitsuModule = new("f7f18a36-8ebb-4db2-b1ea-7bd340579646");

    internal static bool Capture(CombatState combat, IReadOnlyList<AbstractModel> listeners)
    {
        if (typeof(CardModel).Module.ModuleVersionId != GameModule
            || typeof(STS2RitsuLib.Combat.Healing.HealHook).Module.ModuleVersionId != RitsuModule
            || combat.Players.Count != 1)
            return false;
        Type storage = typeof(STS2RitsuLib.Combat.Healing.HealHook).Assembly.GetType("STS2RitsuLib.CardPiles.ModCardPileStorage", true)!;
        bool Patched(MethodBase method) => Harmony.GetPatchInfo(method) is { } patches
            && patches.Owners.Count != 0;
        if (Patched(typeof(ModCardPileRegistry).GetProperty(nameof(ModCardPileRegistry.IsFrozen))!.GetMethod!)
            || Patched(typeof(ModCardPileRegistry).GetMethod(nameof(ModCardPileRegistry.GetDefinitionsSnapshot))!)
            || !ModCardPileRegistry.IsFrozen || ModCardPileRegistry.GetDefinitionsSnapshot().Length != 0)
            return false;
        MirroredHookListenerFilter filter = MirroredHookListenerFilter.Capture();
        if (filter.Filter(listeners) is not MirroredHookListenerSnapshot view
            || view.HasAny(MirroredHookMask.TryModifyKeywordsInCombat))
            return false;

        Assembly runtime = storage.Assembly;
        MethodInfo Getter(Type type, string name) => type.GetProperty(name, Flags)!.GetMethod!;
        MethodInfo Method(Type type, string name) => type.GetMethods(Flags).Single(m => m.Name == name);
        bool Exact(MethodInfo target, MethodInfo[] prefixes, MethodInfo[] postfixes)
        {
            var patches = Harmony.GetPatchInfo(target);
            return (patches is null && prefixes.Length == 0 && postfixes.Length == 0)
                || patches is not null && patches.Transpilers.Count == 0 && patches.Finalizers.Count == 0
                && patches.Prefixes.Count == prefixes.Length && patches.Postfixes.Count == postfixes.Length
                && patches.Prefixes.Select(p => p.PatchMethod).ToHashSet().SetEquals(prefixes)
                && patches.Postfixes.Select(p => p.PatchMethod).ToHashSet().SetEquals(postfixes);
        }
        Type pilePatch = runtime.GetType("STS2RitsuLib.CardPiles.Patches.ModExtraHandCardPileSemanticPatch", true)!;
        Type playerPatch = runtime.GetType("STS2RitsuLib.CardPiles.Patches.ModCardPilePlayerPilesPatch", true)!;
        Type allPatch = runtime.GetType("STS2RitsuLib.CardPiles.Patches.ModCardPileAllPilesPatch", true)!;
        MethodInfo pilePrefix = Method(pilePatch, "Prefix");
        MethodInfo playerPostfix = Method(playerPatch, "Postfix");
        MethodInfo allPostfix = Method(allPatch, "Postfix");
        if (!(Exact(Getter(typeof(CardModel), "Pile"),
                    [pilePrefix, Method(typeof(SimulationCardPileLookupPatch), "Prefix")], [])
                || Exact(Getter(typeof(CardModel), "Pile"), [Method(typeof(SimulationCardPileLookupPatch), "Prefix")], []))
            || !(Exact(Getter(typeof(Player), "Piles"), [], [playerPostfix])
                || Exact(Getter(typeof(Player), "Piles"), [], []))
            || !(Exact(Getter(typeof(PlayerCombatState), "AllPiles"), [], [allPostfix])
                || Exact(Getter(typeof(PlayerCombatState), "AllPiles"), [], [])))
            return false;

        List<MethodBase> reads = [pilePrefix, playerPostfix, allPostfix,
            Method(typeof(SimulationCardPileLookupPatch), "Prefix"),
            Method(typeof(SimulationCardPileLookupFastPath), "CanUse"),
            Method(typeof(SimulationCardPileLookupFastPath), "Find"),
            Getter(typeof(SimulationNotificationIsolation), "IsActive"),
            Method(storage, "GetRunPiles"),
            Method(storage, "GetCombatPiles"),
            Method(typeof(ModCardPileRegistry), "GetCombatDefinitionsSnapshot"),
            typeof(Hook).GetMethod(nameof(Hook.ModifyKeywordsInCombat))!,
            typeof(CardModel).GetMethod(nameof(CardModel.GetKeywordsWithSources))!,
            Getter(typeof(AbstractModel), "IsCanonical"),
            Getter(typeof(AbstractModel), "IsMutable"),
            Getter(typeof(Player), "Creature"), Getter(typeof(Player), "Deck"),
            Getter(typeof(Player), "PlayerCombatState"), Getter(typeof(Creature), "CombatState"),
            Getter(typeof(CardPile), "Cards"), Getter(typeof(CardPile), "IsCombatPile"),
            Getter(typeof(CardPile), "Type")];
        foreach (string name in new[] { "ShouldRetainThisTurn", "IsSlyThisTurn", "Keywords", "LocalKeywords",
            "HasSingleTurnRetain", "HasSingleTurnSly", "CombatState", "UpgradePreviewType" })
            reads.Add(Getter(typeof(CardModel), name));
        foreach (string name in new[] { "Hand", "DrawPile", "DiscardPile", "ExhaustPile", "PlayPile" })
            reads.Add(Getter(typeof(PlayerCombatState), name));
        reads.AddRange(typeof(CardModel).GetMethods(Flags).Where(m => m.Name.Contains("<get_Pile>", StringComparison.Ordinal)));
        if (reads.Any(Patched) || Harmony.GetAllPatchedMethods().Any(m =>
                m.Module.Assembly == typeof(object).Assembly || m.Module.Assembly == typeof(Enumerable).Assembly
                || m.DeclaringType?.FullName?.StartsWith("STS2RitsuLib.Utils.AttachedState", StringComparison.Ordinal) == true))
            return false;

        Player player = combat.Players[0];
        if (player.GetType() != typeof(Player) || player.PlayerCombatState is not { } state
            || state.GetType() != typeof(PlayerCombatState)
            || !StoredPilesAreEmpty(storage, "RunPiles", player)
            || !StoredPilesAreEmpty(storage, "CombatPiles", state))
            return false;
        CardPile[] piles = [state.Hand, state.DrawPile, state.DiscardPile, state.ExhaustPile, state.PlayPile];
        bool Same(object? stored, CardPile[] expected) => stored is null
            || stored.GetType() == typeof(CardPile[]) && ((CardPile[])stored).SequenceEqual(expected);
        if (!Same(typeof(PlayerCombatState).GetField("_piles", Flags)!.GetValue(state), piles)
            || !Same(typeof(Player).GetField("_runPiles", Flags)!.GetValue(player), [player.Deck]))
            return false;
        foreach (CardPile pile in piles.Append(player.Deck))
        {
            if (pile.GetType() != typeof(CardPile) || pile.Cards.GetType() != typeof(List<CardModel>))
                return false;
            foreach (CardModel card in pile.Cards)
            {
                Type type = card.GetType();
                if (type.Module.ModuleVersionId != GameModule
                    || type.GetMethod("Equals", [typeof(object)])!.DeclaringType != typeof(object)
                    || type.GetInterfaces().Any(i => i.IsGenericType && i.GetGenericTypeDefinition() == typeof(IEquatable<>)))
                    return false;
            }
        }
        return true;
    }
    private static bool StoredPilesAreEmpty(Type storage, string name, object key)
    {
        object attached = storage.GetField(name, Flags)!.GetValue(null)!;
        Type attachedType = attached.GetType();
        if (attachedType.Module.ModuleVersionId != new Guid("67c05374-6f96-4bbc-831c-5313d1cc0fd1")
            || attachedType.GetGenericTypeDefinition().FullName != "STS2RitsuLib.Utils.AttachedState`2")
            return false;
        object table = attachedType.GetField("_table", Flags)!.GetValue(attached)!;
        object?[] args = [key, null];
        if (!(bool)table.GetType().GetMethod("TryGetValue")!.Invoke(table, args)!)
            return true;
        object box = args[1]!;
        object? value = box.GetType().GetField("<Value>k__BackingField", Flags)!.GetValue(box);
        return value is IDictionary dictionary && value.GetType().IsGenericType
            && value.GetType().GetGenericTypeDefinition() == typeof(Dictionary<,>) && dictionary.Count == 0;
    }

}

