using System.Reflection;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using HarmonyLib;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Powers;

namespace CombatSolver;

internal sealed partial class UnattendedTestRunner
{
    private static int _nativeKeywordFlagsUnknownCalls;
    private static void NativeKeywordFlagsUnknownPrefix() => _nativeKeywordFlagsUnknownCalls++;

    private void AssertNativeKeywordFlags(CombatState live, Player player, CombatRootSnapshot root)
    {
        if (!root.CanReadLocalKeywordFlags)
            throw new InvalidOperationException("Keyword flags fixture did not obtain the root permission.");
        string liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        int comparisons = 0;
        using IDisposable isolation = SimulationNotificationIsolation.Enter();
        void Compare(PredictedCard card)
        {
            _ = card.Preview.LocalKeywords;
            if (CombatBeamSolver.CaptureCardStateFingerprintForTesting(card, true)
                != CombatBeamSolver.CaptureCardStateFingerprintForTesting(card))
                throw new InvalidOperationException("Keyword flags differed from the actual native getters.");
            if (NativeKeywordFlagsReadCertificate.ShouldRetain(card.Preview, root) != card.Preview.ShouldRetainThisTurn)
                throw new InvalidOperationException("Native retained-card flag differs.");
            comparisons++;
        }
        CardModel[] types = ModelDb.All.OfType<CardModel>().ToArray();
        foreach (CardModel model in types)
        {
            PredictedCard card = PredictedCard.Create(model, player);
            for (int pattern = 0; pattern < 16; pattern++)
            {
                CardModel preview = card.MutablePreview;
                if ((pattern & 1) != 0) preview.AddKeyword(CardKeyword.Sly);
                else preview.RemoveKeyword(CardKeyword.Sly);
                if ((pattern & 2) != 0) preview.AddKeyword(CardKeyword.Retain);
                else preview.RemoveKeyword(CardKeyword.Retain);
                preview._hasSingleTurnSly = (pattern & 4) != 0;
                preview._hasSingleTurnRetain = (pattern & 8) != 0;
                Compare(card);
            }
        }
        CombatPredictionSimulator parent = root.ForkSimulator();
        string parentBefore = DescribeContinuationContractState(parent, root, player);
        CombatPredictionSimulator[] siblings = Enumerable.Range(0, 16).Select(_ => parent.Fork()).ToArray();
        Parallel.For(0, siblings.Length, index =>
        {
            using IDisposable workerIsolation = SimulationNotificationIsolation.Enter();
            CombatPredictionSimulator child = siblings[index];
            PredictedCard card = child.State.GetPlayerCombatState(player).Hand.TopCard!;
            card.MutablePreview._hasSingleTurnRetain = index % 2 == 0;
            card.MutablePreview._hasSingleTurnSly = index % 3 == 0;
            if (CombatBeamSolver.CaptureCardStateFingerprintForTesting(card, true)
                != CombatBeamSolver.CaptureCardStateFingerprintForTesting(card))
                throw new InvalidOperationException("Fork native keyword flags differ.");
            CombatPredictionSimulator grandchild = child.Fork();
            if (DescribeContinuationContractState(child, root, player)
                != DescribeContinuationContractState(grandchild, root, player))
                throw new InvalidOperationException("Keyword flags Fork changed complete state.");
        });
        AbstractModel[] listeners = live.IterateHookListeners().ToArray();
        if (NativeKeywordFlagsReadCertificate.Capture(live, [.. listeners, ModelDb.Power<HexPower>()]))
            throw new InvalidOperationException("A native keyword modifier was certified as a no-op.");
        MethodInfo prefix = typeof(UnattendedTestRunner).GetMethod(nameof(NativeKeywordFlagsUnknownPrefix),
            BindingFlags.Static | BindingFlags.NonPublic)!;
        Harmony harmony = new("CombatSolver.Tests.NativeKeywordFlags");
        int refusals = 0;
        foreach (string name in new[] { "Keywords", "GetKeywordsWithSources", "ShouldRetainThisTurn",
            "IsSlyThisTurn", "LocalKeywords", "HasSingleTurnRetain", "HasSingleTurnSly", "CombatState" })
        {
            MethodInfo target = name == "GetKeywordsWithSources" ? typeof(CardModel).GetMethod(name)!
                : typeof(CardModel).GetProperty(name, BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance)!.GetMethod!;
            try
            {
                harmony.Patch(target, prefix: new HarmonyMethod(prefix));
                if (NativeKeywordFlagsReadCertificate.Capture(live, listeners))
                    throw new InvalidOperationException("Patched keyword read retained the permission: " + name);
                refusals++;
            }
            finally { harmony.Unpatch(target, prefix); }
        }
        if (_nativeKeywordFlagsUnknownCalls != 0
            || parentBefore != DescribeContinuationContractState(parent, root, player)
            || liveBefore != ContinuationStamp.CaptureLive(live).StateText)
            throw new InvalidOperationException("Keyword flags changed parent/live or invoked an unknown reader.");
        _completedChecks.Add($"NativeKeywordFlags:Types={types.Length}:Comparisons={comparisons}:Fork16ParentLiveRng:Refusals={refusals}:UnknownCalls=0");
        Entry.Logger.Info($"[CombatSolver/Test] NATIVE_KEYWORD_FLAGS types={types.Length} comparisons={comparisons} siblings=16 refusals={refusals} unknown_calls=0 parent_live_rng_equal=true");
    }
}

