                || Exact(Getter(typeof(PlayerCombatState), "AllPiles"), [], [])))
            return false;

        List<MethodBase> reads = [pilePrefix, playerPostfix, allPostfix,
            Method(typeof(SimulationCardPileLookupPatch), "Prefix"),
            Method(typeof(SimulationCardPileLookupFastPath), "CanUse"),
            Method(typeof(SimulationCardPileLookupFastPath), "Find"),
            Getter(typeof(SimulationNotificationIsolation), "IsActive"),
            Method(storage, "GetRunPiles"),
            Method(storage, "GetCombatPiles"),
            Method(typeof(ModCardPileRegistry), "GetCombatDefinitionsSnapshot"),
            typeof(Hook).GetMethod(nameof(Hook.ModifyKeywordsInCombat))!,
            typeof(CardModel).GetMethod(nameof(CardModel.GetKeywordsWithSources))!,
            Getter(typeof(AbstractModel), "IsCanonical"),
            Getter(typeof(AbstractModel), "IsMutable"),
            Getter(typeof(Player), "Creature"), Getter(typeof(Player), "Deck"),
            Getter(typeof(Player), "PlayerCombatState"), Getter(typeof(Creature), "CombatState"),
            Getter(typeof(CardPile), "Cards"), Getter(typeof(CardPile), "IsCombatPile"),
            Getter(typeof(CardPile), "Type")];
        foreach (string name in new[] { "ShouldRetainThisTurn", "IsSlyThisTurn", "Keywords", "LocalKeywords",
            "HasSingleTurnRetain", "HasSingleTurnSly", "CombatState", "UpgradePreviewType" })
            reads.Add(Getter(typeof(CardModel), name));
        foreach (string name in new[] { "Hand", "DrawPile", "DiscardPile", "ExhaustPile", "PlayPile" })
            reads.Add(Getter(typeof(PlayerCombatState), name));
        reads.AddRange(typeof(CardModel).GetMethods(Flags).Where(m => m.Name.Contains("<get_Pile>", StringComparison.Ordinal)));
        if (reads.Any(Patched) || Harmony.GetAllPatchedMethods().Any(m =>
                m.Module.Assembly == typeof(object).Assembly || m.Module.Assembly == typeof(Enumerable).Assembly
                || m.DeclaringType?.FullName?.StartsWith("STS2RitsuLib.Utils.AttachedState", StringComparison.Ordinal) == true))
            return false;

        Player player = combat.Players[0];
        if (player.GetType() != typeof(Player) || player.PlayerCombatState is not { } state
            || state.GetType() != typeof(PlayerCombatState)
            || !StoredPilesAreEmpty(storage, "RunPiles", player)
            || !StoredPilesAreEmpty(storage, "CombatPiles", state))
            return false;
        CardPile[] piles = [state.Hand, state.DrawPile, state.DiscardPile, state.ExhaustPile, state.PlayPile];
        bool Same(object? stored, CardPile[] expected) => stored is null
            || stored.GetType() == typeof(CardPile[]) && ((CardPile[])stored).SequenceEqual(expected);
        if (!Same(typeof(PlayerCombatState).GetField("_piles", Flags)!.GetValue(state), piles)
            || !Same(typeof(Player).GetField("_runPiles", Flags)!.GetValue(player), [player.Deck]))
            return false;
        foreach (CardPile pile in piles.Append(player.Deck))
        {
            if (pile.GetType() != typeof(CardPile) || pile.Cards.GetType() != typeof(List<CardModel>))
                return false;
            foreach (CardModel card in pile.Cards)
            {
                Type type = card.GetType();
                if (type.Module.ModuleVersionId != GameModule
                    || type.GetMethod("Equals", [typeof(object)])!.DeclaringType != typeof(object)
                    || type.GetInterfaces().Any(i => i.IsGenericType && i.GetGenericTypeDefinition() == typeof(IEquatable<>)))
                    return false;
            }
        }
        return true;
    }
    private static bool StoredPilesAreEmpty(Type storage, string name, object key)
    {
        object attached = storage.GetField(name, Flags)!.GetValue(null)!;
        Type attachedType = attached.GetType();
        if (attachedType.Module.ModuleVersionId != new Guid("67c05374-6f96-4bbc-831c-5313d1cc0fd1")
            || attachedType.GetGenericTypeDefinition().FullName != "STS2RitsuLib.Utils.AttachedState`2")
            return false;
        object table = attachedType.GetField("_table", Flags)!.GetValue(attached)!;
        object?[] args = [key, null];
        if (!(bool)table.GetType().GetMethod("TryGetValue")!.Invoke(table, args)!)
            return true;
        object box = args[1]!;
        object? value = box.GetType().GetField("<Value>k__BackingField", Flags)!.GetValue(box);
        return value is IDictionary dictionary && value.GetType().IsGenericType
            && value.GetType().GetGenericTypeDefinition() == typeof(Dictionary<,>) && dictionary.Count == 0;
    }

}

