using System.Collections;
using System.Collections.Immutable;
using System.Reflection;
using System.Runtime.CompilerServices;
using CombatSolver.Engine.Common;
using HarmonyLib;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Models;

namespace CombatSolver;

internal static class TaskPileMembershipProof
{
    internal const BindingFlags Fields=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static|BindingFlags.DeclaredOnly;
    internal sealed record Result(bool PileMembershipClosed,ImmutableArray<string> Refusals,int Piles,int Cards,int QueryCards,
        int RunStoredPiles,int CombatStoredPiles,ImmutableArray<string> EqualityBindings,bool WholeHealthCertificate=false);
    internal static FieldInfo Field(Type t,string n)=>t.GetField(n,Fields)??throw new InvalidOperationException("Unknown pile field: "+t.FullName+"."+n);
    internal static MethodInfo Getter(Type t,string n)=>t.GetProperty(n,Fields)?.GetMethod??throw new InvalidOperationException("Unknown pile getter: "+t.FullName+"."+n);
    internal static Type Runtime(string n)=>TaskHandPatchSources.RuntimeType(n);
    internal static MethodInfo Method(Type t,string n)=>t.GetMethods(Fields).Single(m=>m.Name==n);
    internal static Result Capture(Player player,IReadOnlyList<CardModel>? extraQueries=null)
    {
        var reasons=ImmutableArray.CreateBuilder<string>();var bindings=ImmutableArray.CreateBuilder<string>();
        Result Finish(int piles=0,int cards=0,int queries=0,int run=0,int combat=0)=>new(reasons.Count==0,reasons.ToImmutable(),piles,cards,queries,run,combat,bindings.ToImmutable());
        var extension=TaskHandPatchSources.Capture();
        if(!extension.ExtensionSourcesClosed){reasons.AddRange(extension.Refusals);return Finish();}
        if(player.GetType()!=typeof(Player)){reasons.Add("unknown-player-instance");return Finish();}
        var pcs=(PlayerCombatState?)Field(typeof(Player),"<PlayerCombatState>k__BackingField").GetValue(player);
        if(pcs is null||pcs.GetType()!=typeof(PlayerCombatState)){reasons.Add("unknown-player-combat-state");return Finish();}
        var registry=Runtime("STS2RitsuLib.CardPiles.ModCardPileRegistry");
        var storage=Runtime("STS2RitsuLib.CardPiles.ModCardPileStorage");
        var allPatch=Runtime("STS2RitsuLib.CardPiles.Patches.ModCardPileAllPilesPatch");
        var playerPatch=Runtime("STS2RitsuLib.CardPiles.Patches.ModCardPilePlayerPilesPatch");
        var pilePatch=Runtime("STS2RitsuLib.CardPiles.Patches.ModExtraHandCardPileSemanticPatch");
        void Combination(MethodInfo target,MethodInfo[] prefixes,MethodInfo[] postfixes,string label)
        {
            var p=Harmony.GetPatchInfo(target);
            if(p is null||p.Prefixes.Count!=prefixes.Length||p.Postfixes.Count!=postfixes.Length||p.Transpilers.Count+p.Finalizers.Count!=0
                ||!p.Prefixes.Select(x=>x.PatchMethod).ToHashSet().SetEquals(prefixes)
                ||!p.Postfixes.Select(x=>x.PatchMethod).ToHashSet().SetEquals(postfixes))reasons.Add("patch:"+label+"-combination");
        }
        Combination(Getter(typeof(CardModel),"Pile"),[Method(pilePatch,"Prefix"),typeof(SimulationCardPileLookupPatch).GetMethod("Prefix",Fields)!],[],"pile");
        Combination(Getter(typeof(Player),"Piles"),[],[Method(playerPatch,"Postfix")],"player-piles");
        Combination(Getter(typeof(PlayerCombatState),"AllPiles"),[],[Method(allPatch,"Postfix")],"all-piles");
        var sites=new List<MethodBase>{Method(pilePatch,"Prefix"),Method(playerPatch,"Postfix"),Method(allPatch,"Postfix"),
            Method(registry,"GetCombatDefinitionsSnapshot"),Method(storage,"GetRunPiles"),Method(storage,"GetCombatPiles"),
            Getter(typeof(Player),"Deck"),Getter(typeof(Player),"PlayerCombatState"),Getter(typeof(CardPile),"Cards"),
            typeof(SimulationCardPileLookupPatch).GetMethod("Prefix",Fields)!,
            typeof(SimulationCardPileLookupFastPath).GetMethod("CanUse",Fields)!,typeof(SimulationCardPileLookupFastPath).GetMethod("Find",Fields)!,
            typeof(SimulationNotificationIsolation).GetProperty("IsActive",Fields)!.GetMethod!};
        foreach(string n in new[]{"Hand","DrawPile","DiscardPile","ExhaustPile","PlayPile"})sites.Add(Getter(typeof(PlayerCombatState),n));
        sites.AddRange(typeof(CardModel).GetMethods(Fields).Where(m=>m.Name.Contains("<get_Pile>",StringComparison.Ordinal)));
        foreach(var site in sites)if(TaskHandPatchSources.Patched(site))reasons.Add("patch:"+site.DeclaringType!.FullName+"."+site.Name);
        // CLR calls are separately inspected before actual getter/Contains execution.
        foreach(var site in new[]{typeof(List<CardModel>).GetMethod("Contains",[typeof(CardModel)])!,Getter(typeof(List<CardModel>),"Count"),
            Getter(typeof(EqualityComparer<CardModel>),"Default"),typeof(object).GetMethod("Equals",[typeof(object)])!})
            if(TaskHandPatchSources.Patched(site))reasons.Add("patch:clr-reader:"+site.DeclaringType!.Name+"."+site.Name);
        if(Harmony.GetAllPatchedMethods().Any(m=>m.Module.Assembly==typeof(Enumerable).Assembly))reasons.Add("patch:linq-dependency");
        if(reasons.Count!=0)return Finish();
        var snapshot=(Array)Field(registry,"_combatDefinitionsSnapshot").GetValue(null)!;
        if(snapshot.Length!=0){reasons.Add("extra-combat-definition-snapshot");return Finish();}
        int Stored(string name,object key)
        {
            object attached=Field(storage,name).GetValue(null)!;Type type=attached.GetType();
            if(type.Module.ModuleVersionId!=new Guid("67c05374-6f96-4bbc-831c-5313d1cc0fd1")||!type.IsGenericType
                ||type.GetGenericTypeDefinition().FullName!="STS2RitsuLib.Utils.AttachedState`2")
                throw new InvalidOperationException("Unknown attached pile storage.");
            MethodInfo tryAttached=Method(type,"TryGetValue");
            if(TaskHandPatchSources.Patched(tryAttached))throw new PredictionUnsupportedException("patch:attached-pile-reader");
            object table=Field(type,"_table").GetValue(attached)!;Type tableType=table.GetType();
            if(!tableType.IsGenericType||tableType.GetGenericTypeDefinition()!=typeof(ConditionalWeakTable<,>))
                throw new InvalidOperationException("Unknown weak pile storage.");
            var get=tableType.GetMethod("TryGetValue")!;
            if(TaskHandPatchSources.Patched(get))throw new PredictionUnsupportedException("patch:weak-pile-reader");
            object?[] args=[key,null];if(!(bool)get.Invoke(table,args)!)return 0;
            object box=args[1]!;Type boxType=box.GetType();
            var boxGetter=boxType.GetProperty("Value",BindingFlags.Public|BindingFlags.Instance)!.GetMethod!;
            if(TaskHandPatchSources.Patched(boxGetter))throw new PredictionUnsupportedException("patch:attached-box-reader");
            object? value=Field(boxType,"<Value>k__BackingField").GetValue(box);
            if(value is null)throw new PredictionUnsupportedException("unknown-null-pile-storage");
            Type expected=typeof(Dictionary<,>).MakeGenericType(typeof(PileType),Runtime("STS2RitsuLib.CardPiles.ModCardPile"));
            if(value.GetType()!=expected)throw new PredictionUnsupportedException("unknown-pile-storage-map");
            if(TaskHandPatchSources.Patched(Getter(expected,"Count")))throw new PredictionUnsupportedException("patch:stored-pile-count");
            lock(value)return ((IDictionary)value).Count;
        }
        int run=Stored("RunPiles",player),combat=Stored("CombatPiles",pcs);
        if(run!=0)reasons.Add("stored-run-piles:"+run);
        if(combat!=0)reasons.Add("stored-combat-piles:"+combat);
        if(reasons.Count!=0)return Finish(run:run,combat:combat);
        CardPile[] piles=new[]{"Hand","DrawPile","DiscardPile","ExhaustPile","PlayPile"}
            .Select(n=>(CardPile)Field(typeof(PlayerCombatState),"<"+n+">k__BackingField").GetValue(pcs)!).ToArray();
        var deck=(CardPile)Field(typeof(Player),"<Deck>k__BackingField").GetValue(player)!;
        object? cached=Field(typeof(PlayerCombatState),"_piles").GetValue(pcs);
        object? runCached=Field(typeof(Player),"_runPiles").GetValue(player);
        bool Same(object? value,CardPile[] expected)=>value is null||value.GetType()==typeof(CardPile[])
            &&((CardPile[])value).Length==expected.Length&&((CardPile[])value).Where((p,i)=>!ReferenceEquals(p,expected[i])).Any()==false;
        if(!Same(cached,piles))reasons.Add("non-native-combat-pile-cache");
        if(!Same(runCached,[deck]))reasons.Add("non-native-run-pile-cache");
        if(reasons.Count!=0)return Finish(run:run,combat:combat);
        var cards=new List<CardModel>();
        foreach(var pile in piles.Append(deck))
        {
            if(pile.GetType()!=typeof(CardPile)){reasons.Add("unknown-pile-instance");continue;}
            object raw=Field(typeof(CardPile),"_cards").GetValue(pile)!;
            if(raw.GetType()!=typeof(List<CardModel>)){reasons.Add("unknown-card-list");continue;}
            cards.AddRange((List<CardModel>)raw);
        }
        if(cards.Distinct(ReferenceEqualityComparer.Instance).Count()!=cards.Count)reasons.Add("duplicate-card-membership");
        var all=cards.Concat(extraQueries??[]).ToArray();
        foreach(var card in all)
        {
            Type t=card.GetType();var equals=t.GetMethod("Equals",[typeof(object)])!;
            if(equals.DeclaringType!=typeof(object)||t.GetInterfaces().Any(i=>i.IsGenericType&&i.GetGenericTypeDefinition()==typeof(IEquatable<>)))
                {reasons.Add("unknown-card-equality:"+t.FullName);continue;}
            if(t.Module.ModuleVersionId!=typeof(CardModel).Module.ModuleVersionId){reasons.Add("unknown-card-binding:"+t.FullName);continue;}
            bindings.Add(t.FullName+"->System.Object.Equals");
            object? owner=Field(typeof(CardModel),"_owner").GetValue(card);
            if(owner is not null&&!ReferenceEquals(owner,player))reasons.Add("foreign-card-owner");
        }
        return Finish(6,cards.Count,all.Length,run,combat);
    }
}

